#pragma interface

class signaller;

class signal_callback {
public:
    signal_callback()
    {
        disabled = one_shot = false;
        id = id_counter++;
    }
    virtual ~signal_callback() {}

    virtual void spawn(signaller *source = 0) = 0;

    void disable() { disabled = true; }
    void enable() { disabled = false; }
    bool is_disabled() const { return disabled; }
    void set_one_shot(bool value) { one_shot = value; }
    bool is_one_shot() const { return one_shot; }
    unsigned int get_id() const { return id; }
    virtual bool is_code_callback() { return false; }
    virtual bool is_script_callback() { return false; }

protected:
    char *parms;
    bool disabled;
    bool one_shot;
    unsigned int id;

    static unsigned int id_counter;
};

union __default_alloc_object {
    __default_alloc_object *_M_free_list_link;
    char _M_client_data[1];
};

struct __my_default_alloc_template {
    __default_alloc_object *_S_free_list[16];
};

extern __my_default_alloc_template allocator_pool;
__asm__(".equ allocator_pool, 0x003E5628");

struct _List_node_base {
    _List_node_base *_M_next;
    _List_node_base *_M_prev;
};

template<class T>
struct _List_node : public _List_node_base {
    T _M_data;
};

struct _List_iterator_base {
    _List_node_base *_M_node;

    _List_iterator_base() {}
    explicit _List_iterator_base(_List_node_base *node) : _M_node(node) {}

    void _M_incr() { _M_node = _M_node->_M_next; }

    bool operator!=(const _List_iterator_base &other) const
    {
        return _M_node != other._M_node;
    }
};

template<class T, class Ref = T &, class Ptr = T *>
class _List_iterator : public _List_iterator_base {
public:
    typedef _List_node<T> node_type;

    _List_iterator() {}
    _List_iterator(node_type *node) : _List_iterator_base(node) {}

    Ref operator*() const
    {
        return static_cast<node_type *>(_M_node)->_M_data;
    }

    _List_iterator &operator++()
    {
        _M_incr();
        return *this;
    }
};

template<class T>
class list {
public:
    typedef _List_iterator<T, T &, T *> iterator;
    typedef _List_node<T> node_type;

private:
    node_type *_M_node;

    void _M_put_node(node_type *node)
    {
        const unsigned int bytes = (sizeof(node_type) + 7) & ~7;
        const unsigned int index = bytes / 8 - 1;
        __default_alloc_object *object =
            reinterpret_cast<__default_alloc_object *>(node);
        object->_M_free_list_link = allocator_pool._S_free_list[index];
        allocator_pool._S_free_list[index] = object;
    }

public:
    iterator begin()
    {
        return iterator(static_cast<node_type *>(_M_node->_M_next));
    }

    iterator end()
    {
        return iterator(_M_node);
    }

    iterator erase(iterator position)
    {
        _List_node_base *next = position._M_node->_M_next;
        _List_node_base *previous = position._M_node->_M_prev;
        previous->_M_next = next;
        next->_M_prev = previous;
        node_type *node = static_cast<node_type *>(position._M_node);
        _M_put_node(node);
        return iterator(static_cast<node_type *>(next));
    }
};

class signal {
public:
    enum flavor_t {
        SIGNAL,
        GATED_SIGNAL,
        N_FLAVORS
    };

    enum flags_t {
        RAISED = 0x0001,
        NEEDS_REFRESH = 0x0002,
        DISABLED = 0x0004,
        CALLBACKS_DISABLED = 0x0008
    };

    typedef list<signal *> signal_list;
    typedef list<signal_callback *> callback_list;

protected:
    flavor_t flavor;

private:
    unsigned int flags;
    const char *name;
    signal_list *outputs;
    callback_list callbacks;

public:
    signal(signaller *source = 0);
    signal(const char *signal_name, signaller *source = 0);
    virtual ~signal();

    bool is_flagged(flags_t value) const { return flags & value; }
    virtual void refresh();

private:
    signaller *owner;
    virtual void raise_input(signal *input, signaller *source = 0);
    void do_callbacks();
};

void signal::do_callbacks()
{
  if ( !is_flagged(CALLBACKS_DISABLED) )
  {
    {
      callback_list::iterator i = callbacks.begin();

      for ( ; i!=callbacks.end(); )
      {
        signal_callback* c = *i;
        c->spawn( owner );
        if ( c->is_one_shot() )
        {
          delete c;
          i = callbacks.erase( i );
        }
        else
          ++i;
      }
    }
  }
}
